/** biome-ignore-all lint/correctness/noUnusedVariables: Disabled for clarity of the sample  */
/**
 * Sample: defining a strongly typed Kontent.ai delivery model.
 *
 * Top to bottom:
 *  1. Declare your project's schema.
 *  2. Define content item models (validated against the schema).
 *  3. Create a typed delivery client (schema + item union).
 *  4. See how responses narrow at the call site.
 *  5. Filter content items with typed values and operators.
 *
 * Both the schema and the item models are normally generated by `@kontent-ai/model-generator`.
 *
 * In a real consumer project, imports below would come from
 * `@kontent-ai/delivery-sdk`. This sample lives in the SDK repo,
 * so it imports from the in-tree source instead.
 */

import {
	type ContentItemFilter,
	type ContentItemOf,
	createDeliveryClient,
	type DeliveryClient,
	type DeliveryClientSchema,
	type ElementCodenamesOf,
	type Elements,
	type Filter,
	isContentItemOfType,
	type SnippetOf,
	type WorkflowStepCodenameOf,
} from "../lib/public_api.js";

/**
 * 1. Schema declaration
 *
 * `contentTypes` maps each content type to its elements, and each element to its type. Multiple choice
 * elements list their options and taxonomy elements name their taxonomy group, so element models, element
 * values and filters are all checked against the schema. `taxonomies` maps each taxonomy to its term
 * codenames and `workflows` maps each workflow to its step codenames.
 */
export type SampleProjectSchema = DeliveryClientSchema<{
	readonly languageCodenames: readonly ["en-us", "es-es"];
	readonly collectionCodenames: readonly ["movies", "tv-shows"];
	readonly taxonomies: {
		readonly category: readonly ["term1", "term2"];
		readonly categoryActor: readonly ["term3", "term4"];
		readonly tag: readonly ["news", "featured"];
	};
	readonly workflows: {
		readonly default: readonly ["draft", "review", "published"];
		readonly legal: readonly ["draft", "legal_approval", "published"];
	};
	readonly contentTypes: {
		readonly movie: {
			readonly title: { readonly type: "text" };
			readonly rating: { readonly type: "number" };
			readonly synopsis: { readonly type: "rich_text" };
			readonly genre: { readonly type: "multiple_choice"; readonly options: readonly ["genre1", "genre2"] };
			readonly release_date: { readonly type: "date_time" };
			readonly poster: { readonly type: "asset" };
			readonly categories: { readonly type: "taxonomy"; readonly taxonomyGroup: "category" };
			readonly url_slug: { readonly type: "url_slug" };
			readonly custom_id: { readonly type: "custom" };
			readonly actors: { readonly type: "modular_content" };
			readonly metadata__internal_id: { readonly type: "text" };
		};
		readonly actor: {
			readonly first_name: { readonly type: "text" };
			readonly last_name: { readonly type: "text" };
			readonly role: { readonly type: "multiple_choice"; readonly options: readonly ["opt1", "opt2", "opt3"] };
			readonly related_actors: { readonly type: "modular_content" };
			readonly metadata__internal_id: { readonly type: "text" };
			readonly categories: { readonly type: "taxonomy"; readonly taxonomyGroup: "categoryActor" };
		};
	};
}>;

/**
 * 2. Content item models
 *
 * Each property maps an element codename to its element model. `ContentItemOf` checks the element keys
 * and the element types against the schema. Codename generics on `MultipleChoice<...>` and `Taxonomy<...>`
 * are TypeScript hints only: the runtime schema still accepts any codename the API returns.
 */
export type Metadata = SnippetOf<
	SampleProjectSchema,
	"movie" | "actor",
	{
		readonly metadata__internal_id: Elements.Text;
	}
>;

export type Actor = ContentItemOf<
	SampleProjectSchema,
	"actor",
	{
		readonly first_name: Elements.Text;
		readonly last_name: Elements.Text;
		readonly role: Elements.MultipleChoice<"opt1" | "opt2" | "opt3">;
		readonly categories: Elements.Taxonomy<"term3" | "term4", "categoryActor">;
		readonly related_actors: Elements.LinkedItems<Actor>;
	} & Metadata["elements"]
>;

/**
 * `LinkedItems<Actor>` types the resolved `items` of `actors` as `Actor`. `RichText<Actor, "movie">` types
 * the linked items and components in `items` as `Actor` and the content types of linked items (`links[].type`) as "movie".
 */
export type Movie = ContentItemOf<
	SampleProjectSchema,
	"movie",
	{
		readonly title: Elements.Text;
		readonly rating: Elements.Number;
		readonly synopsis: Elements.RichText<Actor, "movie">;
		readonly genre: Elements.MultipleChoice<"genre1" | "genre2">;
		readonly release_date: Elements.DateTime;
		readonly poster: Elements.Asset;
		readonly categories: Elements.Taxonomy<"term1" | "term2", "category">;
		readonly url_slug: Elements.UrlSlug;
		readonly custom_id: Elements.Custom;
		readonly actors: Elements.LinkedItems<Actor>;
	} & Metadata["elements"]
>;

/**
 * The union of all item models. Content item responses are typed as this union.
 */
export type SampleItem = Movie | Actor;

// @ts-expect-error "titel" is not an element codename declared for "movie" in the schema.
export type BadMovieCodename = ContentItemOf<SampleProjectSchema, "movie", { readonly titel: Elements.Text }>;

// @ts-expect-error "title" is a text element, not a number element.
export type BadMovieElementType = ContentItemOf<SampleProjectSchema, "movie", { readonly title: Elements.Number }>;

// @ts-expect-error "genre3" is not an option of the "genre" element.
export type BadMovieOption = ContentItemOf<SampleProjectSchema, "movie", { readonly genre: Elements.MultipleChoice<"genre3"> }>;

// @ts-expect-error "news" is a term of the "tag" taxonomy, but "categories" uses the "category" taxonomy.
export type BadMovieTerm = ContentItemOf<SampleProjectSchema, "movie", { readonly categories: Elements.Taxonomy<"news", "category"> }>;

// A partial shape (only some of the type's elements) is still allowed.
export type PartialMovie = ContentItemOf<SampleProjectSchema, "movie", { readonly title: Elements.Text }>;

/**
 * 3. Typed delivery client
 *
 * Pass the schema and the item union to `createDeliveryClient`.
 */
export type SampleDeliveryClient = DeliveryClient<SampleProjectSchema, SampleItem>;

export const client: SampleDeliveryClient = createDeliveryClient<SampleProjectSchema, SampleItem>({
	apiMode: "public",
	environmentId: "x",
});

/**
 * 4. Demonstration: response typing
 *
 * Each annotated `const` shows what the SDK narrows a response value to.
 */
export async function typedItems(): Promise<void> {
	// Items are typed as the item union.
	const response = await client.fetchContentItem({ codename: "itemCodename" }).fetch();
	const item: SampleItem = response.payload.item;

	// `isContentItemOfType` narrows the union by content type. (TypeScript can't narrow the item by the nested
	// `item.system.type` check, so use the guard instead.)
	if (isContentItemOfType(item, "movie")) {
		const title: string = item.elements.title.value;
		const actors: readonly Actor[] = item.elements.actors.items;
	}

	// @ts-expect-error "moive" is not a content type codename.
	isContentItemOfType(item, "moive");

	// `contentTypes` filters by content type and narrows the returned items.
	const movies = await client.listContentItems({ ofContentTypes: ["movie"] }).fetchPage();
	const movieItems: readonly Movie[] = movies.payload.items;

	// Several content types narrow to their union.
	const feed = await client.itemsFeed({ ofContentTypes: ["movie", "actor"] }).fetchPage();
	const feedItems: readonly (Movie | Actor)[] = feed.payload.items;

	// Linked items in `modular_content` are typed as the item union.
	const linkedItem: SampleItem | undefined = movies.payload.modular_content.some_actor;

	// `workflow_step` narrows once `workflow` is checked.
	const firstMovie = movieItems[0];
	if (firstMovie?.system.workflow === "legal") {
		const step: "draft" | "legal_approval" | "published" = firstMovie.system.workflow_step;
	}
	const allSteps: WorkflowStepCodenameOf<SampleProjectSchema> = "review";
}

/**
 * 5. Demonstration: element value narrowing
 */
export function typedMovie(movie: Movie): void {
	const rating: number | null = movie.elements.rating.value;
	const synopsisActors: readonly Actor[] = movie.elements.synopsis.items;
	const linkType: "movie" | undefined = Object.values(movie.elements.synopsis.links)[0]?.type;
	const genreCodename: "genre1" | "genre2" | undefined = movie.elements.genre.value[0]?.codename;
	const categoryCodename: "term1" | "term2" | undefined = movie.elements.categories.value[0]?.codename;
	const taxonomyGroup: "category" = movie.elements.categories.taxonomy_group;
	const firstActor: Actor | undefined = movie.elements.actors.items[0];
	const actorRole: "opt1" | "opt2" | "opt3" | undefined = firstActor?.elements.role.value[0]?.codename;
}

/**
 * 6. Demonstration: taxonomies and content types
 */
export async function typedTaxonomiesAndTypes(): Promise<void> {
	// Term codenames are narrowed to the terms of the fetched taxonomy, at every nesting level.
	const category = await client.fetchTaxonomy({ codename: "category" }).fetch();
	const termCodename: "term1" | "term2" | undefined = category.payload.terms[0]?.terms[0]?.codename;

	// Listed taxonomies are a union of each taxonomy with its own terms.
	const taxonomies = await client.listTaxonomies().fetchPage();
	const anyTerm: "term1" | "term2" | "term3" | "term4" | "news" | "featured" | undefined =
		taxonomies.payload.taxonomies[0]?.terms[0]?.codename;

	// A fetched content type keeps its codename, and its elements are keyed by the type's element codenames.
	const movieType = await client.fetchContentType({ codename: "movie" }).fetch();
	const movieTypeCodename: "movie" = movieType.payload.system.codename;
	const genreDefinition = movieType.payload.elements.genre;

	// A fetched element is narrowed to its element type.
	const genreElement = await client.fetchContentTypeElement({ typeCodename: "movie", elementCodename: "genre" }).fetch();
	const genreOptions = genreElement.payload.options;

	// @ts-expect-error "first_name" belongs to "actor", not "movie".
	await client.fetchContentTypeElement({ typeCodename: "movie", elementCodename: "first_name" }).fetch();

	const movieElement: ElementCodenamesOf<SampleProjectSchema, "movie"> = "synopsis";
}

/**
 * 7. Demonstration: filters
 *
 * Filter properties, values and operators are checked against the schema. To type a filter array declared
 * outside the query call, use `ContentItemFilter`.
 */
export async function typedFilters(): Promise<void> {
	const filters: readonly ContentItemFilter<SampleProjectSchema>[] = [
		// System properties accept their codenames.
		{ property: "system.type", operator: "in", value: ["movie", "actor"] },
		{ property: "system.language", operator: "eq", value: "en-us" },
		{ property: "system.workflow_step", operator: "neq", value: "draft" },
		// Number elements accept numbers, including ranges.
		{ property: "elements.rating", operator: "range", value: [7, 10] },
		// Taxonomy and multiple choice elements accept their codenames with array operators.
		{ property: "elements.categories", operator: "contains", value: "term3" },
		{ property: "elements.genre", operator: "any", value: ["genre1", "genre2"] },
		// Rich text emptiness uses the SDK helper operators.
		{ property: "elements.synopsis", operator: "isNotEmptyRichText" },
		// Raw string filters are an escape hatch: only the property is checked.
		"elements.genre[any]=genre1,genre2",
	];
	await client.listContentItems({ filters }).fetchPage();
	await client.itemsFeed({ filters }).fetchPage();

	const badFilters: readonly ContentItemFilter<SampleProjectSchema>[] = [
		// @ts-expect-error "titel" is not an element codename declared in the schema.
		{ property: "elements.titel", operator: "eq", value: "Matrix" },
		// @ts-expect-error "moive" is not a content type codename.
		{ property: "system.type", operator: "eq", value: "moive" },
		// @ts-expect-error number elements accept numbers.
		{ property: "elements.rating", operator: "gte", value: "8" },
		// @ts-expect-error "news" is not a term of the "category" taxonomy.
		{ property: "elements.categories", operator: "contains", value: "news" },
		// @ts-expect-error `contains` is an array operator and "title" is a text element.
		{ property: "elements.title", operator: "contains", value: "Matrix" },
		// @ts-expect-error the Delivery API does not support `empty` on rich text, use `isEmptyRichText`.
		{ property: "elements.synopsis", operator: "empty" },
	];

	// The generic `Filter<string, string>` is too wide for content item queries. Use `ContentItemFilter` instead.
	const looseFilters: readonly Filter<string, string>[] = [{ property: "system.type", operator: "eq", value: "movie" }];
	// @ts-expect-error `system.${string}` is wider than the accepted system properties.
	await client.listContentItems({ filters: looseFilters }).fetchPage();
}
